var weChatShareWithImg = {
    init: function() {
        var _this = this
        var firstImgSrc = $(".content.responsivegrid").find("img:first").attr("src");
        var configImgPath = $("meta[name='share-img']").attr("content");
        var weChatImg = _this.handleShareImageUrl(configImgPath||firstImgSrc);
        _this.wechatShare({
            url: window.location.href,
            img: weChatImg,
            title: $("title").text(),
            descript: $("meta[name='description']").attr("content")
        }, function () {});
    },
    handleShareImageUrl: function(imgUrl) {
        if(imgUrl) {
            if(imgUrl.indexOf("https://") == -1 && imgUrl.indexOf("http://") == -1) {
                return "https://" + window.location.host + imgUrl;
            } else {
                return imgUrl;
            }
        } else {
            return imgUrl;
        }
    },
    wechatShare: function(shareModel, successCallback, cancelCallback, errorCallback){
        var signUrl = "https://cuep-cn.hihonor.com/cmkt/services/service/wx/sign?url=" +
                encodeURIComponent(window.location.href.split("#")[0]);
        var appId = "wx926c0beead17f5fa";
        //请求签名
        $.ajax({
            url: signUrl,
            type: "GET",
            dataType: "json",
            jsonp: "jsonp",
            success: function (data) {
                var timestamp = data.timestamp;
                var nonceStr = data.nonceStr;
                var signature = data.signature;
                //配置微信分享
                wx.config({
                    debug: false, // 开启调试模式,调用的所有api的返回值会在客户端alert出来，若要查看传入的参数，可以在pc端打开，参数信息会通过log打出，仅在pc端时才会打印。
                    appId: appId, // 必填，公众号的唯一标识
                    timestamp: timestamp, // 必填，生成签名的时间戳
                    nonceStr: nonceStr, // 必填，生成签名的随机串
                    signature: signature, // 必填，签名，见附录1
                    jsApiList: ["onMenuShareTimeline", "onMenuShareAppMessage"] // 必填，需要使用的JS接口列表，所有JS接口列表见附录2
                });
                var shareInfo = shareModel;

                //微信分享ready
                wx.ready(function () {
                    //取分享的标题
                    var shareTitle = shareInfo.title;
                    //取分享的图片地址
                    var shareImgUrl = shareInfo.img;
                    //取被分享的链接
                    var shareUrl = shareInfo.url;
                    //取被分享的描述
                    var shareDescript = shareInfo.descript;
                    // config信息验证后会执行ready方法，所有接口调用都必须在config接口获得结果之后，config是一个客户端的异步操作，所以如果需要在页面加载时就调用相关接口，则须把相关接口放在ready函数中调用来确保正确执行。对于用户触发时才调用的接口，则可以直接调用，不需要放在ready函数中。
                    wx.onMenuShareTimeline({
                        title: shareTitle, // 分享标题
                        link: shareUrl, // 分享链接
                        imgUrl: shareImgUrl, // 分享图标
                        success: function () {
                            // 用户确认分享后执行的回调函数
                            successCallback && successCallback();
                        },
                        cancel: function () {
                            // 用户取消分享后执行的回调函数
                            cancelCallback && cancelCallback();
                        }
                    });

                    //分享给朋友
                    wx.onMenuShareAppMessage({
                        title: shareTitle, // 分享标题
                        desc: shareDescript, // 分享描述
                        link: shareUrl, // 分享链接
                        imgUrl: shareImgUrl, // 分享图标
                        success: function () {
                            // 用户确认分享后执行的回调函数
                            successCallback && successCallback();
                        },
                        cancel: function () {
                            // 用户取消分享后执行的回调函数
                            cancelCallback && cancelCallback();
                        }
                    });

                });

                wx.error(function (res) {
                    // config信息验证失败会执行error函数，如签名过期导致验证失败，具体错误信息可以打开config的debug模式查看，也可以在返回的res参数中查看，对于SPA可以在这里更新签名。
                    console.log(JSON.stringify(res));
                    errorCallback && errorCallback(res);

                });
            },
            error: function (err) {
                console.error(err);
                errorCallback && errorCallback(res);
            }
        });
    },
    isWeChatBrowser: function(){
        //window.navigator.userAgent属性包含了浏览器类型、版本、操作系统类型、浏览器引擎类型等信息，这个属性可以用来判断浏览器类型
        var ua = window.navigator.userAgent.toLowerCase();
        //通过正则表达式匹配ua中是否含有MicroMessenger字符串
        if(ua.match(/MicroMessenger/i) == 'micromessenger'){
            return true;
        }else{
            return false;
        }
    }
}
$(function () {
    /**
    微信分享使用方式
    1. 引入微信js-sdk 文件  http://res2.wx.qq.com/open/js/jweixin-1.4.0.js
    2. 引入这个文件
    3. 在有自定义分享功能的页面开始的时候或者加载后就该调用  setwxShareConfigInfo(wxConfig, shareData)
    入参
    wxConfig = { // 请求来的jsTicket （必须）
      appId: '', // 必填，公众号的唯一标识
      timestamp: '', // 必填，生成签名的时间戳
      noncestr: '', // 必填，生成签名的随机串
      signature: '', // 必填，签名
    }
    shareData = { // 分享信息和回调  （非必须）
      title: '', // 分享标题 （非必填）
      desc: '', // 分享描述 （非必填）
      link: '', // 分享链接 （非必填）
      imgUrl: '', // 分享缩略图 （非必填）
      success: function, // 分享成功回调（非必填）
      fail: function, // 分享失败回调（非必填）
      cancel: function, // 取消分享回调（非必填）
    }
    */

    if(weChatShareWithImg.isWeChatBrowser()) {
        weChatShareWithImg.init();
    }
});
