            function footerGtm($footerCategory, $linkName) {
                window.dataLayer = window.dataLayer || [];
                if (honorConfig.siteCode == "CN") {
                    var bottomNavigationData = {
                        "actionCode": "bottom_navigation",
                        "eventType": "2",
                        "content": {
                            "event_name": "bottom_navigation",
                            "list_name": $footerCategory || '',
                            "nav_name": $linkName || ''
                        }
                    }
                    sendDapData(bottomNavigationData);
                }
                window.dataLayer.push({
                    "event": "bottom_navigation",
                    "list_name": $footerCategory || '',
                    "nav_name": $linkName || ''
                })
                YandexCommon.track('bottom_navigation', {"list_name": $footerCategory || '', "nav_name": $linkName || ''});
            }

