    questionnaireCustomParameters: window.npsQuestionnaireConfig?.questionnaireCustomParameters || "",//nps问卷中心自定义参数的key名称(aem配置)
    darkStylePageUrlList: window.npsQuestionnaireConfig?.darkStylePageUrlList || [],
