        function isShowViewGAbanner($el) {
            let windH = $(window).height(),
                scrollH = $(window).scrollTop(),
                domTop = $el.offset().top,
                domHeight = $el.height();
            if(domTop < windH + scrollH - 400 && domTop + domHeight > scrollH){
                return true;
            }else{
                return false;
            }
        }

        function viewGAbanner(viewBannerPosition,viewBannerProductName,bannerName) {
            if (honorConfig.siteCode == "CN") {
                window.sendDapData({
                    actionCode: "view_banner",
                    eventType: "7",
                    content: {
                        "event_name": "view_banner",
                        "position": viewBannerPosition,
                        "product_name": viewBannerProductName,
                        "banner_name": bannerName
                    }
                })
            }
            window.dataLayer.push({
                "event": "view_banner",
                "position": viewBannerPosition,
                "product_name": viewBannerProductName,
                "banner_name": bannerName
            })
            YandexCommon.track("view_banner", {position: viewBannerPosition, product_name: viewBannerProductName, banner_name: bannerName})
        }

