template.defaults.imports.ecCurrency = function (num) {
    var currencyUnit = window.currencyUnit;
    //非数字/数字字符不进行转换
    if (isNaN(num)) {
        return num;
    }
    // 当num有传入时才进行千位分隔符、小数点处理
    num = Number(num).toFixed(2);
    num = num.toString();
    //处理当千位分隔符为.时与小数点逻辑冲突
    num = num.replace(/\./g, 'POINT');

    // 处理千位分隔符
    if (window.thousandSeparator !== '') {
        // 组件上配置了千位分隔符，则添加千位分隔符
        num = num.replace(/\d+/, function (n) {
            // 先提取整数部分
            return n.replace(/(\d)(?=(\d{3})+$)/g, function ($1) {
                return $1 + window.thousandSeparator;
            });
        });
    }



    // 处理小数点
    var _newNum = num.split('POINT');
    if (_newNum.length === 2) {
        if (window.decimalPoint !== '') {
            // 组件上配置了小数点，则替换小数点
            num = showDecimal ? _newNum[0] + window.decimalPoint + _newNum[1] : _newNum[0];
        } else {
            // 组件上未配置了小数点，使用默认小数点“.”
            num = showDecimal ? _newNum[0] + '.' + _newNum[1] : _newNum[0];
        }
    }

    // 空格处理
    var space = window.showCurrencySpace ? " " : "";

    //  货币符号处理
    var text = '';
    if (window.putCurrencyFront === true) {
        // 符号置前
        text = currencyUnit + space + num;
    } else {
        // 符号置后
        text = num + space + currencyUnit;
    }

    return text;
};

/**
 *  能效标签模板渲染 
 *  EnergyEfficiency对应接口返回的EnergyEfficiency字段 
 *  pdfFlag是否展示能效的pdf文案，true展示，false不展示
 **/ 
function energyEfficiency(imageHost, EnergyEfficiency, pdfFlag) {
    // 如果没有能效数据或者能效开关未打开，则不进行渲染
    if(!EnergyEfficiency || !window.displayEnergyEfficiencyLabels) return '';
    // Extract small picture and alt text

    // 提取小图和大图信息
    let smallPictureInfo = extractPictureInfo(imageHost, EnergyEfficiency.tinyEnergyEfficiencyNetAdaptWebpPhoto, EnergyEfficiency.tinyEnergyEfficiencyPhoto);
    let bigPictureInfo = extractPictureInfo(imageHost, EnergyEfficiency.energyEfficiencyNetAdaptWebpPhoto, EnergyEfficiency.energyEfficiencyPhoto);

    // 设置图片信息
    EnergyEfficiency.smallPicture = smallPictureInfo.picture;
    EnergyEfficiency.smallPictureAlt = smallPictureInfo.alt;
    EnergyEfficiency.bigPicture = bigPictureInfo.picture;
    EnergyEfficiency.pdfFlag = Boolean(pdfFlag);
    let energyEfficiencyHtml = template("energyEfficiencyTemp", EnergyEfficiency);
    return energyEfficiencyHtml;
};
// 提取图片信息的通用函数
function extractPictureInfo(imageHost, photoInfo, fallbackPhotoInfo) {
    if (photoInfo && photoInfo.photoPath && photoInfo.photoName && imageHost) {
        return {
            picture: imageHost + photoInfo.photoPath + '800_800_90' + photoInfo.photoName,
            alt: photoInfo.altText || ''
        };
    } else if (fallbackPhotoInfo && fallbackPhotoInfo.photoPath && fallbackPhotoInfo.photoName && imageHost) {
        return {
            picture: imageHost + fallbackPhotoInfo.photoPath + '800_800_90' + fallbackPhotoInfo.photoName,
            alt: fallbackPhotoInfo.altText || ''
        };
    } else {
        return {
            picture: '',
            alt: ''
        };
    }
}

template.defaults.imports.energyEfficiency = energyEfficiency;

function getNestedProperty(obj, path) {
    return path.split('.').reduce((acc, part) => acc && acc[part], obj);
}



$(function(){
	var isLogin = sessionStorage.getItem('ec-loginStatus') ? true : false;

	var $inoutData = $(".loginout-data");

	var inoutData = {
		loginUrl: $inoutData.attr("loginurl") || "",
		clientId: $inoutData.attr("clientid") || "",
		loginRedirectURL: window.eqxiuLoginRedirectApi || "",
		logoutRedirectURL: $inoutData.attr("logoutredirecturl") || "",
	};
	var getEqxiuHeaderEndLoginUrl = function (callbackURl) {
		if(callbackURl && callbackURl.startsWith("/")) {
			callbackURl = window.location.origin + callbackURl;
		}
		var callback = callbackURl ? callbackURl : window.location.href;
		var siteCodeForCCPC = honorConfig.siteCodeForCCPC || honorConfig.siteCode.toLowerCase();
		if(honorConfig.siteCode.toLowerCase() == "global"){
			siteCodeForCCPC= "my"
		}
		var siteCodeForAuth = honorConfig.siteCodeForAuth;
		// 登录URL
		var curPage = encodeURIComponent(callback);

		var redirectUri =
			inoutData.loginRedirectURL +"?siteCode="+
			siteCodeForCCPC + "&siteUrl=" +
			curPage;

		//wi, cid, domain, relUrl顺序固定，不可调整
		//页面url中的wi字段有特殊字符;, 获取cps_wi的cookie时需要解码
		if(!siteCodeForCCPC == "cn"){
			if(utils.getCookie("cps_wi")){
				redirectUri += "&wi=" + decodeURIComponent(utils.getCookie("cps_wi"));
			}
			if(utils.getCookie("cps_id")){
				redirectUri += "&cid=" + utils.getCookie("cps_id");
			}
		}
		var scopeVal =
			"openid+" +
			encodeURIComponent(
				"https://www.hihonor.com/auth/account/base.profile"
			) +
			"+" +
			encodeURIComponent(
				"https://www.hihonor.com/auth/account/mobile.number"
			) +
			"+email+" +
			encodeURIComponent("https://www.hihonor.com/auth/account/country") +
			"+" +
			encodeURIComponent("https://www.hihonor.com/auth/account/accountlist");
		var headerEcommerceEndLoginUrl =
			inoutData.loginUrl +
			"?response_type=code&client_id=" +
			inoutData.clientId +
			"&redirect_uri=" +
			encodeURIComponent(redirectUri) +
			"&scope=" +
			scopeVal +
			"&countryCode="+
			siteCodeForAuth +
			"&access_type=offline&themeName=blue&reqClientType=27&loginChannel="+
			(window.innerWidth > 839 ? "27000000" : "27000001")+
			"&lang=" +
			honorConfig.loginLang;

		return headerEcommerceEndLoginUrl;
	};
	$('.honor-game-inlet').on('click',function () {
		if(isLogin) {
			let linkUrl = $(this).parent().find('#game-link').val();
			getEncryptCode(linkUrl)
		} else {
			if($(this).parent().find('#need-login').val() != "true") {
				let link = $(this).parent().find('#game-link').val();
				window.open(link, '_self')
			} else {
				window.open(getEqxiuHeaderEndLoginUrl($(this).parent().find('#game-link').val()), "_self");
			}
		}
	})
	var getEncryptCode = function (link) {
		getEuid().then(function (euid) {
			getEncryptEuid(euid).then(function (code) {
				let linkUrl = link + '&code=' + code;
				window.open(linkUrl, "_self");
			})
		})
	}
	var getEncryptEuid = function (euid) {
		let requestData = {
			euid: euid,
		}
		let url = "sitECommerce/getEncryptEuid"
		var def = $.Deferred();
		ecCom.ajaxReq({
            data: requestData,
            type: "POST",
            api: url,
            apiHost: window.gatewayAPI,
			contentType: "application/json",
            success: function (res) {
                if (res && res.resultCode == 0) {
                    def.resolve(res.data.code)
                }
            },
            error: function(xhr, status, error) {
                def.reject()
            }
        });
        return def.promise();
	}
	var getEuid = function(){
		var def = $.Deferred();
		ecCom.ajaxReq({
			api: 'loginInfo',
			type: 'get'
		}).then(function (response) {
			if (response.data && response.data.euid) {
				def.resolve(response.data.euid);
			}
		});
		return def.promise();
	}
})
