/**
 * ai星标动效，元素进入视口，重新加载图像以触发播放
 */
;(function () {
    function observeAiStar($aiStarImg) {
        const observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                const img = entry.target;
                if (img.classList.contains("ai-star") && entry.isIntersecting) {
                    const originalSrc = img.getAttribute('src');
                    img.src = '';
                    img.src = originalSrc;
                }
            });
        }, {
            threshold: 1
        });

        $aiStarImg.each(function(index, element){
            observer.observe(element);
        })
    }

    $(function(){
        let $aiStarImg = $(".ai-star:not([data-animated])");
        if ($aiStarImg.length > 0) {
            observeAiStar($aiStarImg);
        }
    })
})();
